import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

log_softmax_cuda_code = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

template<typename T>
__inline__ __device__ T warp_reduce_max(T val) {
    #pragma unroll
    for(int offset = 16; offset > 0; offset >>=1) {
        T tmp = __shfl_down_sync(0xffffffff, val, offset);
        val = max(val, tmp);
    }
    return val;
}

template<typename T>
__inline__ __device__ T block_reduce_max(T val) {
    static __shared__ T shared[32];
    int lane = threadIdx.x % 32;
    int wid = threadIdx.x / 32;

    val = warp_reduce_max(val);

    if(lane == 0) shared[wid] = val;
    __syncthreads();

    val = (threadIdx.x < (blockDim.x + 31)/32) ? shared[lane] : (T)-INFINITY;
    if(wid == 0) val = warp_reduce_max(val);
    return val;
}

template<typename T>
__inline__ __device__ T warp_reduce_sum(T val) {
    #pragma unroll
    for(int offset = 16; offset > 0; offset >>=1) {
        val += __shfl_down_sync(0xffffffff, val, offset);
    }
    return val;
}

template<typename T>
__inline__ __device__ T block_reduce_sum(T val) {
    static __shared__ T shared[32];
    int lane = threadIdx.x % 32;
    int wid = threadIdx.x / 32;

    val = warp_reduce_sum(val);

    if(lane == 0) shared[wid] = val;
    __syncthreads();

    val = (threadIdx.x < (blockDim.x + 31)/32) ? shared[lane] : (T)0.0f;
    if(wid == 0) val = warp_reduce_sum(val);
    return val;
}

__global__ void log_softmax_kernel(const float* input, float* output, int dim) {
    const int row = blockIdx.x;
    const int tid = threadIdx.x;
    const int elements_per_thread = dim / blockDim.x;

    float thread_max = -INFINITY;
    for(int i = tid*elements_per_thread; i < (tid+1)*elements_per_thread; i++) {
        thread_max = fmaxf(thread_max, input[row*dim + i]);
    }

    float block_max = block_reduce_max(thread_max);
    __shared__ float smax;
    if(tid == 0) smax = block_max;
    __syncthreads();

    float thread_sum = 0.0f;
    for(int i = tid*elements_per_thread; i < (tid+1)*elements_per_thread; i++) {
        thread_sum += expf(input[row*dim + i] - smax);
    }

    float block_sum = block_reduce_sum(thread_sum);
    __shared__ float ssum;
    if(tid == 0) ssum = block_sum;
    __syncthreads();

    const float log_sum = logf(ssum) + smax;
    for(int i = tid*elements_per_thread; i < (tid+1)*elements_per_thread; i++) {
        output[row*dim + i] = input[row*dim + i] - log_sum;
    }
}

torch::Tensor log_softmax_cuda(torch::Tensor input, int dim) {
    TORCH_CHECK(dim == 1, "Only dim=1 supported");
    auto output = torch::empty_like(input);
    int batch_size = input.size(0);
    int feature_dim = input.size(1);

    const int block_size = 256;
    dim3 grid(batch_size);
    dim3 block(block_size);

    log_softmax_kernel<<<grid, block>>>(input.data_ptr<float>(), output.data_ptr<float>(), feature_dim);
    return output;
}
"""

log_softmax_cpp_code = "torch::Tensor log_softmax_cuda(torch::Tensor input, int dim);"

log_softmax_ext = load_inline(
    name='log_softmax_ext',
    cpp_sources=log_softmax_cpp_code,
    cuda_sources=log_softmax_cuda_code,
    functions=['log_softmax_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, dim: int = 1):
        super().__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return log_softmax_ext.log_softmax_cuda(x, self.dim)
